import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        sc.nextLine();

        String line = sc.nextLine().trim();
        sc.close();

        if (n == 0 || line.isEmpty()) {
            return;
        }

        String[] parts = line.split("\\s+");

        List<String> stringList = Arrays.asList(parts);
        List<Integer> intList = new ArrayList<>();
        boolean isNumeric = true;

        for (String part : parts) {
            try {
                intList.add(Integer.parseInt(part));
            } catch (NumberFormatException e) {
                isNumeric = false;
                break;
            }
        }

        if (isNumeric && intList.size() == n) {
            countFrequency(intList);
        } else {
            countFrequency(stringList);
        }
    }

    public static <T> void countFrequency(List<T> list) {
        HashMap<T, Integer> freqMap = new HashMap<>();

        for (T element : list) {
            freqMap.put(element, freqMap.getOrDefault(element, 0) + 1);
        }

        freqMap.entrySet().stream()
            .sorted(Map.Entry.<T, Integer>comparingByKey().reversed())
            .forEach(entry -> System.out.println(entry.getKey() + " -> " + entry.getValue()));
    }
}
